using System.ComponentModel;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Tools ---

var notebook = new ResearchNotebook();

var tools = new AITool[]
{
    AIFunctionFactory.Create(
        (string query) => WebSearchTool.SearchAsync(query),
        "web_search",
        "Searches the web for a query and returns a list of results with titles, URLs, and snippets."),

    AIFunctionFactory.Create(
        ([Description("The key/title for this note")] string key,
         [Description("The content to save")] string content) =>
        {
            notebook.AddNote(key, content);
            return $"Note saved under '{key}'.";
        },
        "save_note",
        "Saves a research note. Use this to record important findings during research."),

    AIFunctionFactory.Create(
        () => notebook.GetAllNotes(),
        "get_notes",
        "Retrieves all saved research notes as a formatted string."),
};

// --- Agent setup ---

IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

const string instructions = """
    You are a research agent. When given a topic, you:
    1. Search the web for relevant information using the web_search tool (perform 2-3 searches with different queries).
    2. Save important findings using the save_note tool.
    3. After gathering enough information, review your notes with get_notes.
    4. Produce a well-structured summary with key facts, organized by theme, citing sources.
    Be thorough but concise. Always cite your sources with URLs.
    """;

var agent = new ChatClientAgent(
    chatClient,
    instructions: instructions,
    name: "ResearchAgent",
    description: "Researches topics by searching the web and summarizing findings",
    tools: tools);

// --- Run ---

Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var runOptions = new ChatClientAgentRunOptions
{
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 4096,
    },
};

var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    options: runOptions);

Console.WriteLine("═══════════════════════════════════════");
Console.WriteLine("            RESEARCH SUMMARY           ");
Console.WriteLine("═══════════════════════════════════════\n");
Console.WriteLine(response.Text);

if (notebook.Count > 0)
{
    Console.WriteLine("\n───────────────────────────────────────");
    Console.WriteLine($"  📝 {notebook.Count} note(s) saved during research");
    Console.WriteLine("───────────────────────────────────────");
}

// --- Supporting types ---

/// <summary>Simulated web search tool that fetches real results via a free API.</summary>
static class WebSearchTool
{
    private static readonly HttpClient s_http = new();

    public static async Task<string> SearchAsync(string query)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var json = await s_http.GetStringAsync(url);
            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new List<string>();

            // Abstract / instant answer
            var abs = root.GetProperty("Abstract").GetString();
            var absUrl = root.GetProperty("AbstractURL").GetString();
            if (!string.IsNullOrWhiteSpace(abs))
            {
                results.Add($"**Summary**: {abs}\nSource: {absUrl}");
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var item in topics.EnumerateArray().Take(5))
                {
                    var text = item.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    var link = item.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;
                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        results.Add($"- {text}\n  URL: {link}");
                    }
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : $"No detailed results found for '{query}'. Try a different search query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }
}

/// <summary>Simple in-memory notebook for the agent to store research findings.</summary>
sealed class ResearchNotebook
{
    private readonly Dictionary<string, string> _notes = new(StringComparer.OrdinalIgnoreCase);

    public int Count => _notes.Count;

    public void AddNote(string key, string content)
    {
        _notes[key] = content;
        Console.WriteLine($"  📝 Note saved: \"{key}\"");
    }

    public string GetAllNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n\n", _notes.Select(kv => $"## {kv.Key}\n{kv.Value}"));
    }
}

